        b"IPHONEOS_DEPLOYMENT_TARGET=1a.0\n".as_slice(),
        b"IPHONEOS_DEPLOYMENT_TARGET=1 0\n".as_slice(),
        b"IPHONEOS_DEPLOYMENT_TARGET=1=0\n".as_slice(),
